const findings = Array.isArray($json.findings) ? $json.findings : [];

const normativeQueryItems = findings
  .map((finding) => {
    const findingQuery = String(finding.experience_query ?? '').trim();
    if (!findingQuery) {
      return null;
    }

    return {
      finding_id: String(finding.finding_id ?? ''),
      query: [
        'Найти нормативное основание для уже обнаруженного инженерного замечания.',
        'Нужен фрагмент нормативного документа, который прямо относится к указанному факту и типу проектного документа.',
        'Не считать тематически похожий норматив достаточным подтверждением.',
        findingQuery,
      ].join('\n'),
    };
  })
  .filter((item) => item?.finding_id && item?.query);

return {
  json: {
    findings,
    normative_query_items: normativeQueryItems,
    normative_queries: normativeQueryItems.map((item) => item.query),
  },
};

const prepared = $('Prepare Finding Normative Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const queryItems = Array.isArray(prepared.normative_query_items)
  ? prepared.normative_query_items
  : [];
const results = Array.isArray($json.results) ? $json.results : [];

const normativeCandidatesByFinding = {};

for (const finding of findings) {
  normativeCandidatesByFinding[String(finding.finding_id ?? '')] = [];
}

for (let index = 0; index < queryItems.length; index += 1) {
  const queryItem = queryItems[index] ?? {};
  const findingId = String(queryItem.finding_id ?? '');
  if (!findingId) {
    continue;
  }

  const result = results[index] ?? {};
  const rawSources = Array.isArray(result.sources) ? result.sources : [];

  normativeCandidatesByFinding[findingId] = rawSources.map(
    (source, sourceIndex) => ({
      ...source,
      source_id: `NQ${index + 1}_${sourceIndex + 1}`,
    }),
  );
}

return {
  json: {
    findings,
    normative_candidates_by_finding: normativeCandidatesByFinding,
    experience_queries: findings
      .map((finding) => String(finding.experience_query ?? '').trim())
      .filter((query) => query.length > 0),
  },
};

const prepared = $('Prepare Experience Queries').item.json;
const findings = Array.isArray(prepared.findings) ? prepared.findings : [];
const normativeCandidatesByFinding =
  prepared.normative_candidates_by_finding
  && typeof prepared.normative_candidates_by_finding === 'object'
    ? prepared.normative_candidates_by_finding
    : {};
const results = Array.isArray($json.results) ? $json.results : [];
const experienceByFinding = {};

for (let index = 0; index < findings.length; index += 1) {
  const finding = findings[index];
  const result = results[index] ?? {};
  experienceByFinding[finding.finding_id] = Array.isArray(result.sources)
    ? result.sources
    : [];
}

return {
  json: {
    findings,
    normative_candidates_by_finding: normativeCandidatesByFinding,
    experience_by_finding: experienceByFinding,
  },
};

const prepared = $('Prepare Combined Context').item.json;
const understanding = $('Understand Combined Page').item.json;
const queries = $('Build Normative Queries').item.json;
const requirements = $('Normalize Requirement Search').item.json;
const userPackages = $('Search User Packages').item.json;
const check = $('Check Norms').item.json;
const merged = $('Merge Finding Candidates').item.json;
const tFirst = $('Technical Assignment First Pass').item.json;
const enrichment = $('Prepare Experience Queries').item.json;
const augmentation = $('Augment Project Context').item.json;
const finalization = $json;
const findings = (finalization.findings ?? []).map((finding) => ({
  ...finding,
  project_context_sources: augmentation.sources ?? [],
}));

const candidatesByFinding =
  enrichment.normative_candidates_by_finding
  && typeof enrichment.normative_candidates_by_finding === 'object'
    ? enrichment.normative_candidates_by_finding
    : {};
const candidateGroups = Object.values(candidatesByFinding)
  .filter((value) => Array.isArray(value));
const tDecisions = Array.isArray(tFirst.decisions)
  ? tFirst.decisions
  : [];

return { json: {
  status: 'completed',
  source_mode: 'pdf_cad',
  file_name: prepared.source.pdf_file_name,
  pdf_file_name: prepared.source.pdf_file_name,
  cad_file_name: prepared.source.cad_file_name,
  total_pages: prepared.source.total_pdf_pages,
  selected_pages: [prepared.source.selected_page],
  analyzed_pages: 1,
  findings_count: findings.length,
  summary: findings.length ? `Найдено замечаний: ${findings.length}.` : 'Замечания по выбранному PDF + CAD листу не найдены.',
  findings,
  render: prepared.render,
  cad: prepared.cad,
  explanatory_note_context: prepared.project_context,
  page: {
    page_number: prepared.page.page_number,
    heuristic_page_type: prepared.page.page_type,
    width_points: prepared.page.width_points,
    height_points: prepared.page.height_points,
    facts: understanding.facts ?? {},
    normative_queries: queries.queries ?? [],
    normative_sources: requirements.normative_sources ?? [],
    technical_assignment_sources: requirements.technical_assignment_sources ?? [],
    conflict_candidates: requirements.conflict_candidates ?? [],
    requirement_diagnostics: requirements.diagnostics ?? [],
    reference_resolutions: requirements.reference_resolutions ?? [],
    user_package_sources: userPackages.sources ?? [],
    technical_assignment_first_pass: {
      enabled: Boolean(tFirst.enabled),
      requirements_count: Number(tFirst.requirements_count ?? 0),
      decisions_count: tDecisions.length,
      satisfied_count: tDecisions.filter((decision) => decision.status === 'satisfied').length,
      not_applicable_count: tDecisions.filter((decision) => decision.status === 'not_applicable').length,
      violated_count: tDecisions.filter((decision) => decision.status === 'violated').length,
      needs_review_count: tDecisions.filter((decision) => decision.status === 'insufficient_evidence').length,
      findings_count: Array.isArray(tFirst.findings) ? tFirst.findings.length : 0,
      summary: String(tFirst.summary ?? ''),
      metrics: Array.isArray(tFirst.metrics) ? tFirst.metrics : [],
    },
    finding_candidates: {
      normative_check_count: Array.isArray(check.findings) ? check.findings.length : 0,
      merged_count: Array.isArray(merged.findings) ? merged.findings.length : 0,
    },
    normative_enrichment: {
      queries_count: $('Prepare Finding Normative Queries').item.json.normative_queries?.length ?? 0,
      candidates_count: candidateGroups.reduce((total, sources) => total + sources.length, 0),
    },
    normative_check: { summary: check.summary ?? '', findings: check.findings ?? [], metrics: check.metrics ?? {} },
    project_context_sources: augmentation.sources ?? [],
  },
  pipeline: ['combined_document_extract','explanatory_note_validation','temporary_project_context_index','technical_assignment_requirement_feed','page_understanding','technical_assignment_first_pass','project_context_retrieval','normative_queries','requirement_search','user_package_search','normative_check','finding_candidate_merge','finding_normative_search','experience_search','finalization','project_context_cleanup'],
  limitations: ['Контекст ПЗ и пользовательские пакеты являются контекстом проекта, а не нормативным доказательством.', 'Техническое задание проверяется независимым exhaustive T-first проходом и не является нормативным доказательством.', 'T-guided retrieval используется дополнительно и не управляет сохранением T-first findings.', 'Дополнительный нормативный поиск не удаляет инженерные замечания при отсутствии подтверждения.', 'Точное расположение finding на изображении будет добавлено на этапе визуализации.'],
} };

const technicalAssignmentId = String(
  $('POST /analysis/v2/pdf-cad').first().json.body?.technical_assignment_id ?? '',
).trim();

if (!technicalAssignmentId) {
  return [{
    json: {
      enabled: false,
      technical_assignment_id: null,
      analysis_document_id: null,
      section_id: null,
      source_file: '',
      source_sha256: '',
      total: 0,
      requirements: [],
    },
  }];
}

const pages = $input.all().map((item) => item.json ?? {});

if (pages.length === 0) {
  throw new Error('T-first requirement feed вернул пустой набор страниц.');
}

const first = pages[0];
const expectedDocumentId = String(
  $('POST /analysis/v2/pdf-cad').first().json.body?.document_id ?? '',
).trim();
const expectedSectionId = String(
  $('POST /analysis/v2/pdf-cad').first().json.body?.normative_section_id ?? '',
).trim();

const total = Number(first.total ?? 0);

if (!Number.isInteger(total) || total < 1) {
  throw new Error(
    `T-first requirement feed должен содержать хотя бы одно atomic requirement; total=${first.total}.`,
  );
}

if (total > 1000) {
  throw new Error(
    `T-first requirement feed превышает configured Analysis limit: total=${total}, limit=1000.`,
  );
}

const requirements = pages
  .flatMap((page) => Array.isArray(page.requirements) ? page.requirements : [])
  .sort(
    (left, right) =>
      Number(left.requirement_index ?? 0) - Number(right.requirement_index ?? 0),
  );

for (const page of pages) {
  if (String(page.technical_assignment_id ?? '') !== technicalAssignmentId) {
    throw new Error('T-first requirement feed содержит другой technical_assignment_id.');
  }

  if (String(page.analysis_document_id ?? '') !== expectedDocumentId) {
    throw new Error('T-first requirement feed содержит другой analysis_document_id.');
  }

  if (String(page.section_id ?? '') !== expectedSectionId) {
    throw new Error('T-first requirement feed содержит другой section_id.');
  }

  if (Number(page.total ?? -1) !== total) {
    throw new Error('T-first requirement feed содержит несовместимые total между страницами.');
  }

  if (
    String(page.source_file ?? '') !== String(first.source_file ?? '')
    || String(page.source_sha256 ?? '') !== String(first.source_sha256 ?? '')
  ) {
    throw new Error('T-first requirement feed содержит несовместимые source metadata.');
  }
}

if (requirements.length !== total) {
  throw new Error(
    `T-first requirement feed получен не полностью: expected=${total}, actual=${requirements.length}.`,
  );
}

const requirementIds = requirements.map(
  (requirement) => String(requirement.requirement_id ?? ''),
);

if (
  requirementIds.some((requirementId) => !requirementId)
  || new Set(requirementIds).size !== requirementIds.length
) {
  throw new Error('T-first requirement feed содержит пустые или повторяющиеся requirement_id.');
}

return [{
  json: {
    enabled: true,
    technical_assignment_id: technicalAssignmentId,
    analysis_document_id: expectedDocumentId,
    section_id: expectedSectionId,
    source_file: String(first.source_file ?? ''),
    source_sha256: String(first.source_sha256 ?? ''),
    total,
    requirements,
  },
}];

const enabled = Boolean(
  $('Prepare Combined Context').item.json.technical_assignment?.enabled,
);

if (!enabled) {
  return {
    json: {
      enabled: false,
      requirements_count: 0,
      summary: '',
      decisions: [],
      findings: [],
      metrics: [],
    },
  };
}

const response = $json ?? {};
const decisions = Array.isArray(response.decisions) ? response.decisions : [];
const findings = Array.isArray(response.findings) ? response.findings : [];
const metrics = Array.isArray(response.metrics) ? response.metrics : [];
const requirementsCount = Number(
  $('Prepare Combined Context').item.json.technical_assignment?.total ?? 0,
);

if (decisions.length !== requirementsCount) {
  throw new Error(
    `T-first потеряла atomic decisions: expected=${requirementsCount}, actual=${decisions.length}.`,
  );
}

const decisionIds = decisions.map(
  (decision) => String(decision.requirement_id ?? ''),
);
const expectedIds = $('Prepare Combined Context').item.json.technical_assignment.requirements
  .map((requirement) => String(requirement.requirement_id ?? ''));

if (
  decisionIds.length !== expectedIds.length
  || decisionIds.some((requirementId) => !requirementId)
  || new Set(decisionIds).size !== decisionIds.length
  || expectedIds.some((requirementId, index) => requirementId !== decisionIds[index])
) {
  throw new Error('T-first decisions не соответствуют полному ordered atomic requirement feed.');
}

return {
  json: {
    enabled: true,
    requirements_count: requirementsCount,
    summary: String(response.summary ?? ''),
    decisions,
    findings,
    metrics,
  },
};

const normativeCheck = $json ?? {};
const normativeFindings = Array.isArray(normativeCheck.findings)
  ? normativeCheck.findings
  : [];
const technicalAssignment = $('Technical Assignment First Pass').item.json ?? {};
const technicalAssignmentFindings = Array.isArray(technicalAssignment.findings)
  ? technicalAssignment.findings
  : [];

const findings = [
  ...normativeFindings,
  ...technicalAssignmentFindings,
];

const findingIds = findings.map(
  (finding) => String(finding.finding_id ?? ''),
);

if (
  findingIds.some((findingId) => !findingId)
  || new Set(findingIds).size !== findingIds.length
) {
  throw new Error(
    'Finding candidate merge обнаружил пустой или повторяющийся finding_id.',
  );
}

return {
  json: {
    ...normativeCheck,
    findings,
    technical_assignment_first_pass: {
      enabled: Boolean(technicalAssignment.enabled),
      requirements_count: Number(
        technicalAssignment.requirements_count ?? 0,
      ),
      decisions_count: Array.isArray(technicalAssignment.decisions)
        ? technicalAssignment.decisions.length
        : 0,
      findings_count: technicalAssignmentFindings.length,
      summary: String(technicalAssignment.summary ?? ''),
      metrics: Array.isArray(technicalAssignment.metrics)
        ? technicalAssignment.metrics
        : [],
    },
  },
};
